    for (platform, nxt), mass in states.items():
        if nxt <= 100:
            # The platform is full while balls remain on the ramp.
            for pos in range(3):
                branch = mass / 3.0
                hit = platform[pos]
                ejected[hit] += branch
                if pos == 0:
                    new_platform = (platform[1], platform[2], nxt)
                    new_nxt = nxt + 1
