                    new_platform = (platform[1], nxt, nxt + 1)
                    new_nxt = nxt + 2

                if new_nxt <= 100:
                    key = (new_platform, new_nxt)
                    next_states[key] = next_states.get(key, 0.0) + branch
                else:
                    # Ramp is exhausted; carry the remaining occupied balls
                    # into a terminal-resolution state.
                    key = (new_platform, new_nxt)
                    next_states[key] = next_states.get(key, 0.0) + branch
        else:
            # After ball 100 enters, condition on occupied positions only.
            k = len(platform)
            if k == 0:
                continue
            for pos in range(k):
                branch = mass / k
                hit = platform[pos]
                ejected[hit] += branch
                if pos == 0:
                    new_platform = platform[1:]
                elif pos == 1:
                    released[platform[0]] += branch
                    new_platform = platform[2:]
                else:
                    released[platform[0]] += branch
                    new_platform = (platform[1],)

                if new_platform:
                    key = (tuple(new_platform), nxt)
                    next_states[key] = next_states.get(key, 0.0) + branch
    states = next_states

best_probability = max(ejected.values())
best_balls = [n for n in ejected if abs(ejected[n] - best_probability) < 1e-12]
top_ten = sorted(ejected.items(), key=lambda item: item[1], reverse=True)[:10]
summary = {
    "best_balls": best_balls,
    "best_probability": best_probability,
    "top_ten": top_ten,
    "probability_check": sum(ejected.values()) + sum(released.values())
}
print(summary)
